-- NXT Hotspot – Phase 2 reference schema (PostgreSQL 14+)
-- Design reference: the EF Core model/migrations are authoritative. Diff against `dotnet ef migrations script`.
-- Run on an empty database:  psql -v ON_ERROR_STOP=1 -d nxthotspot -f 001_phase2_schema.sql

BEGIN;

CREATE TABLE "OrganizationTypes" (
    "OrganizationTypeId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "TypeName"    varchar(100) NOT NULL,
    "Description" varchar(500),
    "IsActive"    boolean NOT NULL DEFAULT true,
    "CreatedAt"   timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt"   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "UX_OrganizationTypes_TypeName" UNIQUE ("TypeName")
);

CREATE TABLE "OrganizationTypeLoginMethods" (
    "Id" uuid PRIMARY KEY,
    "OrganizationTypeId" integer NOT NULL REFERENCES "OrganizationTypes"("OrganizationTypeId") ON DELETE CASCADE,
    "AuthenticationType" varchar(50) NOT NULL,
    "IsDefault" boolean NOT NULL DEFAULT false,
    "RequireOTP" boolean NOT NULL DEFAULT false,
    "RequireBookingValidation" boolean NOT NULL DEFAULT false,
    "AllowMultipleDevices" boolean NOT NULL DEFAULT true,
    "MaxDevices" integer NOT NULL DEFAULT 2 CHECK ("MaxDevices" >= 1),
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "UX_OrgTypeLoginMethods_Type_Auth" UNIQUE ("OrganizationTypeId", "AuthenticationType")
);
CREATE UNIQUE INDEX "UX_OrgTypeLoginMethods_OneDefault" ON "OrganizationTypeLoginMethods" ("OrganizationTypeId") WHERE "IsDefault";

CREATE TABLE "SubscriptionPlans" (
    "Id" uuid PRIMARY KEY,
    "Name" varchar(100) NOT NULL,
    "MaxSites" integer CHECK ("MaxSites" IS NULL OR "MaxSites" >= 1),
    "MonthlyPrice" numeric(14,2) NOT NULL DEFAULT 0 CHECK ("MonthlyPrice" >= 0),
    "IsActive" boolean NOT NULL DEFAULT true,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "UX_SubscriptionPlans_Name" UNIQUE ("Name")
);

CREATE TABLE "Organizations" (
    "Id" uuid PRIMARY KEY,
    "Name" varchar(200) NOT NULL,
    "OrganizationTypeId" integer NOT NULL REFERENCES "OrganizationTypes"("OrganizationTypeId") ON DELETE RESTRICT,
    "ContactPerson" varchar(150) NOT NULL,
    "MobileNumber" varchar(20) NOT NULL,
    "Email" varchar(254) NOT NULL,
    "Address" varchar(500),
    "Status" varchar(20) NOT NULL,
    "SubscriptionPlanId" uuid REFERENCES "SubscriptionPlans"("Id") ON DELETE RESTRICT,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "CK_Organizations_Status" CHECK ("Status" IN ('Active','Suspended','Inactive'))
);
CREATE INDEX "IX_Organizations_Status" ON "Organizations" ("Status");
CREATE INDEX "IX_Organizations_OrganizationTypeId" ON "Organizations" ("OrganizationTypeId");
CREATE INDEX "IX_Organizations_Name" ON "Organizations" ("Name");

CREATE TABLE "OrganizationSettings" (
    "Id" uuid PRIMARY KEY,
    "OrganizationId" uuid NOT NULL REFERENCES "Organizations"("Id") ON DELETE CASCADE,
    "OtpExpirySeconds" integer NOT NULL DEFAULT 300 CHECK ("OtpExpirySeconds" BETWEEN 30 AND 3600),
    "OtpResendCooldownSeconds" integer NOT NULL DEFAULT 30 CHECK ("OtpResendCooldownSeconds" BETWEEN 0 AND 3600),
    "OtpMaxAttempts" integer NOT NULL DEFAULT 5 CHECK ("OtpMaxAttempts" BETWEEN 1 AND 20),
    "SessionValiditySeconds" integer NOT NULL DEFAULT 86400 CHECK ("SessionValiditySeconds" >= 60),
    "DefaultMaxDevices" integer NOT NULL DEFAULT 2 CHECK ("DefaultMaxDevices" >= 1),
    "DefaultDataLimitMb" integer CHECK ("DefaultDataLimitMb" IS NULL OR "DefaultDataLimitMb" > 0),
    "TimeZone" varchar(64) NOT NULL DEFAULT 'Asia/Kolkata',
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "UX_OrganizationSettings_OrganizationId" UNIQUE ("OrganizationId")
);

CREATE TABLE "OrganizationBranding" (
    "Id" uuid PRIMARY KEY,
    "OrganizationId" uuid NOT NULL REFERENCES "Organizations"("Id") ON DELETE CASCADE,
    "LogoUrl" varchar(500),
    "WelcomeMessage" varchar(500),
    "ThemeColor" varchar(9) NOT NULL DEFAULT '#0d6efd',
    "BackgroundUrl" varchar(500),
    "TermsAndConditions" text,
    "PrivacyPolicy" text,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "UX_OrganizationBranding_OrganizationId" UNIQUE ("OrganizationId")
);

CREATE TABLE "Sites" (
    "Id" uuid PRIMARY KEY,
    "OrganizationId" uuid NOT NULL REFERENCES "Organizations"("Id") ON DELETE CASCADE,
    "Code" varchar(30) NOT NULL,
    "Name" varchar(150) NOT NULL,
    "Address" varchar(500),
    "City" varchar(100),
    "IsPrimary" boolean NOT NULL DEFAULT false,
    "IsActive" boolean NOT NULL DEFAULT true,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "UX_Sites_Org_Code" UNIQUE ("OrganizationId", "Code"),
    CONSTRAINT "CK_Sites_PrimaryIsActive" CHECK (NOT "IsPrimary" OR "IsActive")
);
CREATE UNIQUE INDEX "UX_Sites_OnePrimaryPerOrg" ON "Sites" ("OrganizationId") WHERE "IsPrimary";

CREATE TABLE "OrganizationLoginMethods" (
    "Id" uuid PRIMARY KEY,
    "OrganizationId" uuid NOT NULL REFERENCES "Organizations"("Id") ON DELETE CASCADE,
    "SiteId" uuid REFERENCES "Sites"("Id") ON DELETE CASCADE,
    "AuthenticationType" varchar(50) NOT NULL,
    "IsEnabled" boolean NOT NULL DEFAULT true,
    "IsDefault" boolean NOT NULL DEFAULT false,
    "RequireOTP" boolean NOT NULL DEFAULT false,
    "RequireBookingValidation" boolean NOT NULL DEFAULT false,
    "AllowMultipleDevices" boolean NOT NULL DEFAULT true,
    "MaxDevices" integer NOT NULL DEFAULT 2 CHECK ("MaxDevices" >= 1),
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX "UX_OrgLoginMethods_Org_Auth" ON "OrganizationLoginMethods" ("OrganizationId", "AuthenticationType") WHERE "SiteId" IS NULL;
CREATE UNIQUE INDEX "UX_OrgLoginMethods_Site_Auth" ON "OrganizationLoginMethods" ("OrganizationId", "SiteId", "AuthenticationType") WHERE "SiteId" IS NOT NULL;
CREATE UNIQUE INDEX "UX_OrgLoginMethods_Org_Default" ON "OrganizationLoginMethods" ("OrganizationId") WHERE "IsDefault" AND "SiteId" IS NULL;
CREATE UNIQUE INDEX "UX_OrgLoginMethods_Site_Default" ON "OrganizationLoginMethods" ("SiteId") WHERE "IsDefault" AND "SiteId" IS NOT NULL;

CREATE TABLE "OrganizationSmsSettings" (
    "Id" uuid PRIMARY KEY,
    "OrganizationId" uuid REFERENCES "Organizations"("Id") ON DELETE CASCADE,
    "SiteId" uuid REFERENCES "Sites"("Id") ON DELETE CASCADE,
    "ProviderName" varchar(50) NOT NULL,
    "ApiEndpoint" varchar(500) NOT NULL,
    "ApiKeyEncrypted" text NOT NULL,
    "SenderId" varchar(20) NOT NULL,
    "MessageTemplate" varchar(500) NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT true,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "CK_OrgSms_SiteNeedsOrg" CHECK ("SiteId" IS NULL OR "OrganizationId" IS NOT NULL)
);
CREATE UNIQUE INDEX "UX_OrgSms_Org" ON "OrganizationSmsSettings" ("OrganizationId") WHERE "SiteId" IS NULL AND "OrganizationId" IS NOT NULL;
CREATE UNIQUE INDEX "UX_OrgSms_Site" ON "OrganizationSmsSettings" ("SiteId") WHERE "SiteId" IS NOT NULL;
CREATE UNIQUE INDEX "UX_OrgSms_PlatformDefault" ON "OrganizationSmsSettings" ("ProviderName") WHERE "OrganizationId" IS NULL AND "SiteId" IS NULL;

CREATE TABLE "AdminUsers" (
    "Id" uuid PRIMARY KEY,
    "OrganizationId" uuid REFERENCES "Organizations"("Id") ON DELETE RESTRICT,
    "Username" varchar(100) NOT NULL,
    "NormalizedUsername" varchar(100) NOT NULL,
    "FullName" varchar(150) NOT NULL,
    "Email" varchar(254),
    "PasswordHash" text NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT true,
    "HasAllSitesAccess" boolean NOT NULL DEFAULT false,
    "FailedLoginCount" integer NOT NULL DEFAULT 0,
    "LockoutEndUtc" timestamptz,
    "LastLoginAt" timestamptz,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "UX_AdminUsers_NormalizedUsername" UNIQUE ("NormalizedUsername")
);
CREATE INDEX "IX_AdminUsers_OrganizationId" ON "AdminUsers" ("OrganizationId");

CREATE TABLE "Roles" (
    "Id" uuid PRIMARY KEY,
    "OrganizationId" uuid REFERENCES "Organizations"("Id") ON DELETE CASCADE,
    "Name" varchar(100) NOT NULL,
    "Description" varchar(300),
    "IsSystem" boolean NOT NULL DEFAULT false,
    "IsPlatformRole" boolean NOT NULL DEFAULT false,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "CK_Roles_PlatformRoleHasNoOrg" CHECK (NOT "IsPlatformRole" OR "OrganizationId" IS NULL)
);
CREATE UNIQUE INDEX "UX_Roles_Org_Name" ON "Roles" ("OrganizationId", "Name") WHERE "OrganizationId" IS NOT NULL;
CREATE UNIQUE INDEX "UX_Roles_Global_Name" ON "Roles" ("Name") WHERE "OrganizationId" IS NULL;

CREATE TABLE "Permissions" (
    "Id" uuid PRIMARY KEY,
    "Code" varchar(100) NOT NULL,
    "Description" varchar(300),
    "IsPlatformOnly" boolean NOT NULL DEFAULT false,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "UX_Permissions_Code" UNIQUE ("Code")
);

CREATE TABLE "RolePermissions" (
    "RoleId" uuid NOT NULL REFERENCES "Roles"("Id") ON DELETE CASCADE,
    "PermissionId" uuid NOT NULL REFERENCES "Permissions"("Id") ON DELETE CASCADE,
    PRIMARY KEY ("RoleId", "PermissionId")
);

CREATE TABLE "AdminUserRoles" (
    "AdminUserId" uuid NOT NULL REFERENCES "AdminUsers"("Id") ON DELETE CASCADE,
    "RoleId" uuid NOT NULL REFERENCES "Roles"("Id") ON DELETE RESTRICT,
    PRIMARY KEY ("AdminUserId", "RoleId")
);
CREATE INDEX "IX_AdminUserRoles_RoleId" ON "AdminUserRoles" ("RoleId");

CREATE TABLE "AdminUserSites" (
    "AdminUserId" uuid NOT NULL REFERENCES "AdminUsers"("Id") ON DELETE CASCADE,
    "SiteId" uuid NOT NULL REFERENCES "Sites"("Id") ON DELETE CASCADE,
    PRIMARY KEY ("AdminUserId", "SiteId")
);
CREATE INDEX "IX_AdminUserSites_SiteId" ON "AdminUserSites" ("SiteId");

CREATE TABLE "SiteWallets" (
    "Id" uuid PRIMARY KEY,
    "OrganizationId" uuid NOT NULL REFERENCES "Organizations"("Id") ON DELETE RESTRICT,
    "SiteId" uuid NOT NULL REFERENCES "Sites"("Id") ON DELETE CASCADE,
    "Balance" numeric(14,2) NOT NULL DEFAULT 0,
    "Currency" char(3) NOT NULL DEFAULT 'INR',
    "Version" bigint NOT NULL DEFAULT 0,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "UX_SiteWallets_SiteId" UNIQUE ("SiteId"),
    CONSTRAINT "CK_SiteWallets_Balance_NonNegative" CHECK ("Balance" >= 0)
);
CREATE INDEX "IX_SiteWallets_OrganizationId" ON "SiteWallets" ("OrganizationId");

CREATE TABLE "SiteWalletTransactions" (
    "Id" uuid PRIMARY KEY,
    "OrganizationId" uuid NOT NULL REFERENCES "Organizations"("Id") ON DELETE RESTRICT,
    "SiteId" uuid NOT NULL REFERENCES "Sites"("Id") ON DELETE RESTRICT,
    "Type" varchar(10) NOT NULL CHECK ("Type" IN ('Credit','Debit')),
    "Amount" numeric(14,2) NOT NULL CHECK ("Amount" > 0),
    "BalanceAfter" numeric(14,2) NOT NULL CHECK ("BalanceAfter" >= 0),
    "Sequence" bigint NOT NULL,
    "Reference" varchar(100),
    "Description" varchar(500),
    "IdempotencyKey" varchar(100),
    "CreatedByAdminUserId" uuid,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "UX_SiteWalletTransactions_Site_Sequence" UNIQUE ("SiteId", "Sequence")
);
CREATE UNIQUE INDEX "UX_SiteWalletTransactions_Site_Idempotency" ON "SiteWalletTransactions" ("SiteId", "IdempotencyKey") WHERE "IdempotencyKey" IS NOT NULL;
CREATE INDEX "IX_SiteWalletTransactions_OrganizationId" ON "SiteWalletTransactions" ("OrganizationId");

-- Append-only audit trail. Deliberately no foreign keys: entries must outlive the rows they describe.
CREATE TABLE "AuditLogs" (
    "Id" uuid PRIMARY KEY,
    "OrganizationId" uuid,
    "AdminUserId" uuid,
    "Action" varchar(100) NOT NULL,
    "EntityType" varchar(100),
    "EntityId" varchar(100),
    "Details" text,
    "IpAddress" varchar(64),
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX "IX_AuditLogs_Org_CreatedAt" ON "AuditLogs" ("OrganizationId", "CreatedAt" DESC);
CREATE INDEX "IX_AuditLogs_Action" ON "AuditLogs" ("Action");

COMMIT;
